(async () => {
  const browser = await chromium.launch({
    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome',
    headless: true,
  });

  const page = await browser.newPage();

  // Load HTML file
  const htmlPath = 'file:///app/output/malaria-poster.html';
  await page.goto(htmlPath, { waitUntil: 'networkidle' });

  // Wait a bit for fonts and charts to render
  await page.waitForTimeout(3000);

  // Get the poster element
  const poster = await page.$('#poster');
  const box = await poster.boundingBox();

  // A1 at 150 DPI ≈ 3508 x 4961 px
  // But let's compute scale from the designed width of 1400px
  const targetWidth = 3508;
  const scale = targetWidth / box.width;
  const targetHeight = Math.round(box.height * scale);

  console.log(`Poster box: ${Math.round(box.width)}x${Math.round(box.height)}`);
  console.log(`Target: ${targetWidth}x${targetHeight}, scale: ${scale}`);

  // Take screenshot of the poster element at high resolution
  await poster.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
  });

  // Now resize to exact A1 dimensions using sharp if available, or report
  await browser.close();

  const stats = fs.statSync('/app/output/final_poster.png');
  console.log(`Output file size: ${stats.size} bytes`);
})();
