node << 'NODE_SCRIPT'
const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({
    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome',
    headless: true,
  });

  const context = await browser.newContext({
    viewport: { width: 1600, height: 2400 },
    deviceScaleFactor: 2.6,
  });

  const page = await context.newPage();

  const logs = [];
  page.on('console', msg => logs.push(msg.text()));
  page.on('pageerror', err => logs.push('ERROR: ' + err.message));

  await page.goto('file:///app/output/malaria-poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(6000);

  logs.forEach(l => console.log(l));

  // Check if infographic containers have rendered SVG content
  const compareHtml = await page.$eval('#ig-compare', el => el.innerHTML.length);
  const chartHtml = await page.$eval('#ig-chart', el => el.innerHTML.length);
  console.log(`Compare innerHTML length: ${compareHtml}`);
  console.log(`Chart innerHTML length: ${chartHtml}`);

  await browser.close();
})();
NODE_SCRIPT

